&= \E_{(\line, \line_X, \line_Z) \sim D} \E_{(x,z,\alpha, \beta) \in \line} \sum_{a} \bra{\hat{\psi}}  T^{\line_X, \line_Z,x}_{a} \ot  (\Id-\hat{M}^{(\Point,X),x}_{a})^2 \ket{\hat{\psi}}\notag\\
